import{_ as r,K as l,a as d,c as n,ac as e,b as o,q as i}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"乒乓球规则","description":"按 ITTF 11 分制梳理乒乓球单打、双打的发球、轮换、计分、擦边擦网与常见判例。","frontmatter":{"title":"乒乓球规则","description":"按 ITTF 11 分制梳理乒乓球单打、双打的发球、轮换、计分、擦边擦网与常见判例。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"球类运动规则","summary":"按 ITTF 11 分制梳理乒乓球单打、双打的发球、轮换、计分、擦边擦网与常见判例。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"篮球规则 · 常见判例与误解至官方资料与阅读范围","link":"/life/personal/sports/basketball-rules-part-02"},"next":{"text":"羽毛球规则","link":"/life/personal/sports/badminton-rules"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"篮球规则 · 常见判例与误解至官方资料与阅读范围","link":"/life/personal/sports/basketball-rules-part-02"},"next":{"text":"羽毛球规则","link":"/life/personal/sports/badminton-rules"}},"headers":[],"relativePath":"life/personal/sports/table-tennis-rules.md","filePath":"life/personal/sports/table-tennis-rules.md"}'),s={name:"life/personal/sports/table-tennis-rules.md"};function h(p,t,b,c,u,g){const a=l("ArticleImage");return d(),n("div",null,[t[0]||(t[0]=e('<h1 id="乒乓球规则" tabindex="-1">乒乓球规则 <a class="header-anchor" href="#乒乓球规则" aria-label="Permalink to &quot;乒乓球规则&quot;">​</a></h1><p>乒乓球的基本目标是把球合法回到对方台面，并让对方无法合法回球。入门时先掌握三件事：每局怎样结束、发球怎样合法、双打怎样轮流击球。</p><h2 id="适用范围与规则版本" tabindex="-1">适用范围与规则版本 <a class="header-anchor" href="#适用范围与规则版本" aria-label="Permalink to &quot;适用范围与规则版本&quot;">​</a></h2><p>本文以 ITTF《2025 Statutes》中第 2 章《The Laws of Table Tennis》的 <strong>11 分制常规单打、双打</strong> 为学习口径，暂停与局间休息参考国际竞赛规程。团体赛的出场顺序、整场采用几局几胜，以及赛事特别规定，需另看竞赛规程。</p><p>这里不采用过去的 21 分制，也不展开轮椅项目的特殊条款。规则条号便于查原文；后续版本或具体赛事有修订时，以其公布的生效版本为准。</p><h2 id="人数、球台与器材" tabindex="-1">人数、球台与器材 <a class="header-anchor" href="#人数、球台与器材" aria-label="Permalink to &quot;人数、球台与器材&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>规则要点</th></tr></thead><tbody><tr><td>单打、双打</td><td>单打每方 1 人；双打每方 2 人</td></tr><tr><td>球台</td><td>长 2.74 米、宽 1.525 米，台面离地 0.76 米</td></tr><tr><td>球网</td><td>网顶距台面 15.25 厘米</td></tr><tr><td>比赛用球</td><td>直径 40 毫米，重 2.7 克，白色或橙色，无光泽</td></tr><tr><td>球拍</td><td>一面黑色，另一面采用能与黑色及球明显区分的明亮颜色；不再只有红黑一种配色</td></tr><tr><td>有效台面</td><td>包含上表面的边缘，不包含球台垂直侧面</td></tr></tbody></table><p>双打中线宽 3 毫米，将两端台区各分成左右两半。判断双打发球时，中线视为右半区的一部分。单打发球不受这条中线限制。</p><h2 id="看图理解双打发球" tabindex="-1">看图理解双打发球 <a class="header-anchor" href="#看图理解双打发球" aria-label="Permalink to &quot;看图理解双打发球&quot;">​</a></h2>',9)),o("p",null,[i(a,{src:"/images/sports/table-tennis-table.svg",alt:"乒乓球台比例图：双打发球先落本方右半区再落对方右半区"})]),t[1]||(t[1]=e('<p><em>图：球台按 2.74 × 1.525 米比例绘制。下方是发球方；上方接发者面向下，所以他的“右半区”在画面左侧。①② 是先后落点，不是只能在这些点附近击球。台高 0.76 米、网高 15.25 厘米为垂直尺寸，俯视图不表现高度。</em></p><p>双打发球的斜线限制只管这一拍的两次落台。球被合法接回后，可以打向对方任何有效台面，但仍须按双方队员交替的次序击球。图中线把左右半区分开，<strong>并没有限制球员只能站在自己的半边</strong>。</p><h2 id="计分、换发球与换边" tabindex="-1">计分、换发球与换边 <a class="header-anchor" href="#计分、换发球与换边" aria-label="Permalink to &quot;计分、换发球与换边&quot;">​</a></h2><p>每个有效回合的胜方得 1 分，与谁发球无关。一局先到 11 分且至少领先 2 分者获胜；10∶10 后继续打到领先 2 分，例如 12∶10、16∶14，<strong>没有 15 分或 21 分封顶</strong>。整场由奇数局组成，常见为五局三胜或七局四胜，由赛事规定。</p><p>通常每人连续发 2 球，然后交换发球权；10∶10 以后每人只发 1 球，直到该局结束。发球触网且其他条件合法而重发，不算已完成一分，也不消耗一个发球次数。</p><p>赛前抽签决定先发球、先接发球或先选场地；一方作出选择，另一方选择剩余项目。相邻两局交换场地，并交换先发球的一方。决胜局一方先得 <strong>5 分</strong> 时再次交换场地。忘记换边时应立即纠正，已经产生的得分仍有效。</p><h3 id="一个单打例子" tabindex="-1">一个单打例子 <a class="header-anchor" href="#一个单打例子" aria-label="Permalink to &quot;一个单打例子&quot;">​</a></h3><p>甲先发球：第 1、2 分甲发，第 3、4 分乙发，依此类推。这里的“第几分”是双方累计完成的回合数，不是某个人的得分。到 10∶10 时轮到甲发，则接下来依次甲、乙、甲、乙，每人一球。</p><h2 id="怎样发出一个合法球" tabindex="-1">怎样发出一个合法球 <a class="header-anchor" href="#怎样发出一个合法球" aria-label="Permalink to &quot;怎样发出一个合法球&quot;">​</a></h2><p>ITTF 规则 2.6 的重点是让接发球员能看清从抛球到击球的过程。</p><ol><li>球静止放在伸平的、不持拍手的手掌上，不能握住或用手指夹住。</li><li>将球近乎垂直向上抛起，不主动施加旋转；球离开手掌后至少上升 <strong>16 厘米</strong>。</li><li>球下降时才能击球。不能球还在上升就击打，也不能直接从手里喂到球拍上。</li><li>从发球开始到击球，球要在台面以上、发球方端线之后；不能用身体、手臂、衣物或双打同伴遮挡接发球员的视线。</li><li>抛球后，不持拍手和手臂应立即从球与球网之间的空间移开。</li><li>击球后，球先落在本方台面，再落到对方台面。单打可以直线发球；双打必须依次落在本方右半区、对方右半区。</li></ol><p>发球没有“失误一次再发一次”的机会。没有抛够高度、遮挡、发空、未先落本方台面或双打落错半区，都可能直接失分。裁判对合法性有疑问时可按规则作首次警告，但明显的非法发球不需要先警告。</p><h3 id="发球擦网与普通回球擦网" tabindex="-1">发球擦网与普通回球擦网 <a class="header-anchor" href="#发球擦网与普通回球擦网" aria-label="Permalink to &quot;发球擦网与普通回球擦网&quot;">​</a></h3><table tabindex="0"><thead><tr><th>情形</th><th>处理</th></tr></thead><tbody><tr><td>发球擦网后，仍按要求落入对方有效台区</td><td>重发，比分不变</td></tr><tr><td>发球擦网后出界，或双打落错半区</td><td>发球方失分</td></tr><tr><td>相持中擦网后落在对方有效台面</td><td>继续比赛</td></tr><tr><td>接发球员尚未准备好，且没有尝试接球</td><td>可判重发；不能先尝试接球，失误后再以没准备好要求重发</td></tr></tbody></table><p>合法的擦网重发可以连续出现，没有“第三次擦网就丢分”的通用规则。</p><h2 id="回球、擦边与失分" tabindex="-1">回球、擦边与失分 <a class="header-anchor" href="#回球、擦边与失分" aria-label="Permalink to &quot;回球、擦边与失分&quot;">​</a></h2><p>接球方应让来球在自己台面弹起一次，再将球击回对方台面；不能像网球那样在台面上方直接截击，也不能等它弹两次才击球。</p><p>常见失分包括：回球未上对方台面、球在本方台面弹两次、故意连续击球、双打击球次序错误、比赛中移动球台、身体或穿戴物触及球网装置，以及不持拍手触及台面。</p><p>以下几个边界尤其容易误判：</p><ul><li><strong>擦上沿有效，打侧面无效。</strong> 判断接触的是台面上表面还是垂直侧面，而不是只看球是否突然改变方向。</li><li><strong>球可以绕过网柱。</strong> 回球无需始终从网顶上方穿过，只要符合其他规则并落在对方台面即可。</li><li><strong>持拍手触球可能有效。</strong> 持拍手手腕以下碰到球属于击球定义范围；手臂、身体碰球不在此列。</li><li><strong>不是所有两次接触都判失分。</strong> 规则针对故意连续击球；一个连续击球动作中的意外双碰，不应简单等同于故意连击。</li><li><strong>不是任何部位碰台都失分。</strong> 不持拍手触台面是明确失分情形；持拍手、身体接触球台仍须看是否移动台面等。不要用这个区别冒险扑压球台。</li><li><strong>接住已经出界的球不等于一律阻挡。</strong> 若球未触本方台面，已经越过本方端线，接住它通常不构成阻挡；球仍在台面上方或朝台面飞行时提前拦住，则可能失分。</li></ul><h2 id="双打-发球顺序与击球顺序" tabindex="-1">双打：发球顺序与击球顺序 <a class="header-anchor" href="#双打-发球顺序与击球顺序" aria-label="Permalink to &quot;双打：发球顺序与击球顺序&quot;">​</a></h2><p>双打不是两名队友谁顺手谁击球，而是 <strong>每一拍都必须交替</strong>。</p><p>假设甲、乙为一队，丙、丁为另一队，本局先由甲发给丙：</p><table tabindex="0"><thead><tr><th>发球轮次</th><th>发球员 → 接发球员</th></tr></thead><tbody><tr><td>第一轮两球</td><td>甲 → 丙</td></tr><tr><td>第二轮两球</td><td>丙 → 乙</td></tr><tr><td>第三轮两球</td><td>乙 → 丁</td></tr><tr><td>第四轮两球</td><td>丁 → 甲</td></tr></tbody></table><p>随后循环。记忆方法是：每次换发球，<strong>刚才的接发球员变成发球员，刚才发球员的同伴变成接发球员</strong>。10∶10 后仍按同一顺序，只是每轮变成一球。</p><p>甲发给丙的这一回合，击球必须是“甲发球 → 丙接发 → 乙回球 → 丁回球 → 甲回球……”；即使球正好到了甲面前，该轮应由乙击球时也不能代打。</p><p>每局开始，先发球一方确定本局谁先发；第一局由接发球一方确定谁先接。后续各局，先接发球者应是上一局向本局先发球员发球的人，不能随意重排。决胜局一方先到 5 分时，除了换场地，还要由接发球一方交换接发顺序。</p><p>发现发接球顺序错了，应暂停并按正确顺序恢复；错误被发现前的得分保留。不要自行倒扣已经完成的分数。</p><h2 id="间歇与比赛节奏" tabindex="-1">间歇与比赛节奏 <a class="header-anchor" href="#间歇与比赛节奏" aria-label="Permalink to &quot;间歇与比赛节奏&quot;">​</a></h2><p>国际竞赛通常允许每局之间最多 1 分钟休息，每名运动员或每对双打在一场比赛中可请求一次最长 1 分钟的暂停。每局双方得分合计每满 6 分可以短暂擦汗，决胜局换边时也可以擦汗；这些不是每 6 分都能另加一次战术暂停。</p><p>长时间防守相持还可能适用“轮换发球法”：通常一局进行到 10 分钟仍未结束时启动，但双方合计已有至少 18 分则不启动。启动后每人每次发一球，接发球方在一个回合完成 13 次正确回击即可得分，并延续到该场比赛结束。日常约球一般较少遇到，正式比赛由裁判执行。</p><h2 id="新手怎样打完一局" tabindex="-1">新手怎样打完一局 <a class="header-anchor" href="#新手怎样打完一局" aria-label="Permalink to &quot;新手怎样打完一局&quot;">​</a></h2><ol><li>赛前确认几局几胜，通过抽签选发接球或场地；双打要说清第一对发接球员。</li><li>每分开始先报比分，再确认发球员。平时连续发两球；10∶10 后改为一人一球，双打的人员轮转顺序保留。</li><li>发球后双方按次序回击；球落地、出界或发生犯规，确认这一分归谁，再调整发球次序。</li><li>一方达到至少 11 分且领先两分时结束本局，记录局分并换场。决胜局一方先到 5 分还有一次换边。</li></ol><h3 id="三个带比分的例子" tabindex="-1">三个带比分的例子 <a class="header-anchor" href="#三个带比分的例子" aria-label="Permalink to &quot;三个带比分的例子&quot;">​</a></h3><ul><li><strong>甲 10∶乙 9，由甲发球。</strong> 甲合法发球擦网后落对方台面，判重发，仍是 10∶9；下一次乙回球出界，才变为 11∶9，本局结束。重发不是“甲已用完一个发球”。</li><li><strong>双打甲乙 8∶丙丁 8。</strong> 甲发给丙，丙接回后，甲抢在乙前面又打了一拍：甲乙击球次序错误，丙丁得分，变为 8∶9。球是否成功上台不改变次序犯规。</li><li><strong>甲 11∶乙 10。</strong> 乙的回球擦到甲方台面的上边缘，甲没接到，是 11∶11；若碰到的只有垂直侧面，则乙的回球无效，甲以 12∶10 获胜。不能听到“擦边”就跳过接触面的判断。</li></ul><h3 id="观赛常用词" tabindex="-1">观赛常用词 <a class="header-anchor" href="#观赛常用词" aria-label="Permalink to &quot;观赛常用词&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>看球时怎样理解</th></tr></thead><tbody><tr><td>接发球</td><td>对方合法发球后的第一拍，必须先让球落本方台面</td></tr><tr><td>相持</td><td>发接球后双方持续交换回球；没有规定必须打够几拍</td></tr><tr><td>搓球、拉球</td><td>常见击球方式，分别常用于处理短球、制造弧线与旋转；不是独立的得分规则</td></tr><tr><td>局点、赛点</td><td>再赢一分就可能赢下这一局、整场；必须结合领先两分等条件</td></tr><tr><td>重发（let）</td><td>该回合不计分，恢复原有发球；不同于发球失误直接失分</td></tr><tr><td>轮换发球法</td><td>正式规则中的加速比赛制度，别与平时每两分换发球混为一谈</td></tr></tbody></table><p>双打配合的第一件事是打完这一拍后给同伴留出击球空间。它属于配合方法，规则本身不强制两人按某个圆圈路线移动。</p><h2 id="常见判例与自测" tabindex="-1">常见判例与自测 <a class="header-anchor" href="#常见判例与自测" aria-label="Permalink to &quot;常见判例与自测&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>判断与理由</th></tr></thead><tbody><tr><td>10∶10 后甲连得两分</td><td>甲以 12∶10 获胜；这两分应按一人一球发球</td></tr><tr><td>单打从本方左半区发到对方左半区</td><td>可以；左右半区限制用于双打发球</td></tr><tr><td>双打发球压在对方中线上</td><td>视为落在右半区，其他条件满足即合法</td></tr><tr><td>发球连续三次擦网且都落对台有效区</td><td>三次都重发，比分不变</td></tr><tr><td>相持球擦网，随后落在对方台面</td><td>好球，继续回合</td></tr><tr><td>双打同一人连续接了两拍</td><td>次序错误，该方失分</td></tr><tr><td>关键分球打中球台垂直侧面</td><td>没有落到有效台面，击球方失分</td></tr></tbody></table><p>自己再回答三题：</p><ol><li>甲以 11∶10 领先，本局结束了吗？</li><li>球抛起只有 10 厘米，但对手顺利接到了，发球就合法吗？</li><li>决胜局打到 6∶3 才发现忘记换边，前一分要取消吗？</li></ol><p><strong>答案：</strong> ①没有，还需领先 2 分。②不合法，能接到不代表发球动作符合规则。③不取消，立即纠正场地，已得分保留。</p><h2 id="官方来源与查阅方法" tabindex="-1">官方来源与查阅方法 <a class="header-anchor" href="#官方来源与查阅方法" aria-label="Permalink to &quot;官方来源与查阅方法&quot;">​</a></h2><ul><li><a href="https://www.ittf.com/handbook/" target="_blank" rel="noopener noreferrer">ITTF 官方 Handbook 入口</a>：查找适用年度 Statutes；第 2 章涵盖台面、发球、回球、重发、得分、换序和轮换发球法。</li><li><a href="https://documents.ittf.sport/" target="_blank" rel="noopener noreferrer">ITTF 官方 Documents 资料库</a>：检索 “2025 ITTF Statutes”，核对第 2.6—2.15 条；休息和暂停查国际竞赛规程第 3.4.4 节。</li><li><a href="https://www.ittf.com/2021/07/22/table-tennis-101/" target="_blank" rel="noopener noreferrer">ITTF：Table Tennis 101</a>：球台尺寸及上表面边缘、侧面的区别。</li><li><a href="https://documents.ittf.sport/document/354" target="_blank" rel="noopener noreferrer">2025 Statutes 官方版本记录</a>；<a href="https://documents.ittf.sport/document/389" target="_blank" rel="noopener noreferrer">2026 Statutes 官方版本记录</a>：2026 版已公布，本页保留 2025 版学习口径，不把旧版称为当前最新版。</li></ul><p>本文是规则的中文学习整理，尚未完成对所列版本官方原文的逐条校核。正式参赛请以官方规则为准，并确认赛事的局数、器材与暂停等具体安排。</p>',46))])}const k=r(s,[["render",h]]);export{m as __pageData,k as default};
